const viralPosts = [
  {
    hook: '🎸 Learning guitar shouldn\'t cost $15/month for Ubisoft Rocksmith+.',
    body: 'We built GRYF: a 100% free, open-source web app that runs in any browser.\n\n⚡ Sub-5ms pitch detection (AudioWorklet + YIN)\n⚡ 3D note highway with Rocksmith string colors\n⚡ Zero installation — works with standard microphone or USB interface\n\nTry it live: http://92.118.206.90:3000\nGitHub: https://github.com/merx666/gryf-guitar',
    tags: ['#Guitar', '#OpenSource', '#WebDev', '#JavaScript', '#Rocksmith', '#MusicTech'],
    mediaUrl: 'http://92.118.206.90:3000/banner-social.svg'
  },
  {
    hook: '🔥 Drop ANY MP3 or YouTube link -> get instant guitar tabs & 3D highway sync.',
    body: 'Gryf AI Studio separates guitar stems with Demucs v4 and aligns notes note-for-note down to 5ms.\n\n• Solo the lead guitar to learn tricky solos\n• Mute the guitar to play with the real backing track\n• Export synced GPX & MIDI files\n\n100% open-source: https://github.com/merx666/gryf-guitar\nLive demo: http://92.118.206.90:3000',
    tags: ['#Gryf', '#GuitarTabs', '#AI', '#Demucs', '#WebAudio', '#RockGuitar'],
    mediaUrl: 'http://92.118.206.90:3000/banner-github.svg'
  },
  {
    hook: '⚡ Can Web Audio API replace a $2,000 guitar amplifier rig?',
    body: 'Gryf includes in-browser physical tube emulation, 50Hz hum filter, BBD analog stereo chorus and tape delay with zero latency.\n\nPlug your guitar directly into your browser: http://92.118.206.90:3000\nStar the repo on GitHub: https://github.com/merx666/gryf-guitar',
    tags: ['#WebAudio', '#GuitarPedals', '#DSP', '#AudioWorklet', '#OpenSource'],
    mediaUrl: 'http://92.118.206.90:3000/banner-social.svg'
  },
  {
    hook: '🚀 Master of Puppets intro riff tested at 212 BPM on our WebGL 3D note highway.',
    body: 'Instant visual feedback, streak multiplier flames, and pitch lock strobe tuner.\n\nFree open-source rhythm learning: http://92.118.206.90:3000\nContribute: https://github.com/merx666/gryf-guitar',
    tags: ['#Metallica', '#GuitarHero', '#Rocksmith', '#MetalGuitar', '#WebDev'],
    mediaUrl: 'http://92.118.206.90:3000/banner-github.svg'
  }
];

// Losowy lub sekwencyjny wybór posta
const index = Math.floor(Math.random() * viralPosts.length);
const selected = viralPosts[index];

return [{
  json: {
    timestamp: new Date().toISOString(),
    postText: `${selected.hook}\n\n${selected.body}\n\n${selected.tags.join(' ')}`,
    mediaUrl: selected.mediaUrl,
    targetPlatforms: ['x_twitter', 'reddit_promo', 'discord_announcements'],
    status: 'ready_to_publish'
  }
}];
